import java.util.*;

// Carries whatever data needs to flow through the chain
class Request {
    private String path;
    private String authToken;
    private Map<String, String> attributes = new HashMap<>();

    public Request(String path, String authToken) {
        this.path = path;
        this.authToken = authToken;
    }

    public String getPath() {
        return path;
    }

    public String getAuthToken() {
        return authToken;
    }

    public void setAttribute(String key, String value) {
        attributes.put(key, value);
    }

    public String getAttribute(String key) {
        return attributes.get(key);
    }
}

// Every middleware implements this single method
interface Middleware {
    void handle(Request request, Runnable next);
}

class LoggingMiddleware implements Middleware {
    @Override
    public void handle(Request request, Runnable next) {
        System.out.println("[LOG] incoming request for " + request.getPath());
        next.run(); // hands control to whatever comes next, then waits here
        System.out.println("[LOG] finished handling " + request.getPath());
    }
}

class AuthMiddleware implements Middleware {
    @Override
    public void handle(Request request, Runnable next) {
        String token = request.getAuthToken();
        if (token == null || !token.equals("valid-token")) {
            System.out.println("[AUTH] rejected, missing or invalid token");
            return; // short circuits here, next is never called
        }
        request.setAttribute("user", "verified-user");
        System.out.println("[AUTH] token accepted, request continues");
        next.run();
    }
}

class FinalHandler {
    public void handle(Request request) {
        System.out.println("[HANDLER] serving " + request.getPath() + " for " + request.getAttribute("user"));
    }
}

// Wires an ordered list of middlewares plus a terminal handler into one callable chain
class MiddlewareChain {
    private final List<Middleware> middlewares;
    private final FinalHandler finalHandler;

    public MiddlewareChain(List<Middleware> middlewares, FinalHandler finalHandler) {
        this.middlewares = middlewares;
        this.finalHandler = finalHandler;
    }

    public void run(Request request) {
        execute(0, request);
    }

    private void execute(int index, Request request) {
        if (index == middlewares.size()) {
            finalHandler.handle(request);
            return;
        }
        Middleware current = middlewares.get(index);
        current.handle(request, () -> execute(index + 1, request));
    }
}

public class Main {
    public static void main(String[] args) {
        MiddlewareChain chain = new MiddlewareChain(
            Arrays.asList(new LoggingMiddleware(), new AuthMiddleware()),
            new FinalHandler()
        );

        System.out.println("Request with a valid token:");
        chain.run(new Request("/orders", "valid-token"));

        System.out.println("Request with no token:");
        chain.run(new Request("/orders", null));
    }
}

