class Request:
    """Carries whatever data needs to flow through the chain."""

    def __init__(self, path, auth_token):
        self.path = path
        self.auth_token = auth_token
        self.attributes = {}

    def set_attribute(self, key, value):
        self.attributes[key] = value

    def get_attribute(self, key):
        return self.attributes.get(key)


class LoggingMiddleware:
    def handle(self, request, next_fn):
        print(f"[LOG] incoming request for ${request.path}")
        next_fn()  # hands control to whatever comes next, then waits here
        print(f"[LOG] finished handling ${request.path}")


class AuthMiddleware:
    def handle(self, request, next_fn):
        if request.auth_token != "valid-token":
            print("[AUTH] rejected, missing or invalid token")
            return  # short circuits here, next_fn is never called
        request.set_attribute("user", "verified-user")
        print("[AUTH] token accepted, request continues")
        next_fn()


class FinalHandler:
    def handle(self, request):
        print(f"[HANDLER] serving ${request.path} for ${request.get_attribute('user')}")


class MiddlewareChain:
    """Wires an ordered list of middlewares plus a terminal handler into one callable chain."""

    def __init__(self, middlewares, final_handler):
        self.middlewares = middlewares
        self.final_handler = final_handler

    def run(self, request):
        self._execute(0, request)

    def _execute(self, index, request):
        if index == len(self.middlewares):
            self.final_handler.handle(request)
            return
        current = self.middlewares[index]
        current.handle(request, lambda: self._execute(index + 1, request))


if __name__ == "__main__":
    chain = MiddlewareChain([LoggingMiddleware(), AuthMiddleware()], FinalHandler())

    print("Request with a valid token:")
    chain.run(Request("/orders", "valid-token"))

    print("Request with no token:")
    chain.run(Request("/orders", None))

