#include <iostream>
#include <string>
#include <vector>
#include <functional>
#include <map>
#include <memory>
using namespace std;

class Request {
public:
    string path;
    string authToken;
    map<string, string> attributes;

    Request(string path, string authToken) : path(path), authToken(authToken) {}

    void setAttribute(const string& key, const string& value) {
        attributes[key] = value;
    }

    string getAttribute(const string& key) {
        auto it = attributes.find(key);
        return it != attributes.end() ? it->second : "";
    }
};

// Every middleware implements this single method
class Middleware {
public:
    virtual void handle(Request& request, function<void()> next) = 0;
    virtual ~Middleware() {}
};

class LoggingMiddleware : public Middleware {
public:
    void handle(Request& request, function<void()> next) override {
        cout << "[LOG] incoming request for " << request.path << endl;
        next(); // hands control to whatever comes next, then waits here
        cout << "[LOG] finished handling " << request.path << endl;
    }
};

class AuthMiddleware : public Middleware {
public:
    void handle(Request& request, function<void()> next) override {
        if (request.authToken != "valid-token") {
            cout << "[AUTH] rejected, missing or invalid token" << endl;
            return; // short circuits here, next is never called
        }
        request.setAttribute("user", "verified-user");
        cout << "[AUTH] token accepted, request continues" << endl;
        next();
    }
};

class FinalHandler {
public:
    void handle(Request& request) {
        cout << "[HANDLER] serving " << request.path << " for " << request.getAttribute("user") << endl;
    }
};

// Wires an ordered list of middlewares plus a terminal handler into one callable chain
class MiddlewareChain {
    vector<shared_ptr<Middleware>> middlewares;
    FinalHandler finalHandler;

public:
    MiddlewareChain(vector<shared_ptr<Middleware>> middlewares, FinalHandler finalHandler)
        : middlewares(middlewares), finalHandler(finalHandler) {}

    void run(Request& request) {
        execute(0, request);
    }

private:
    void execute(int index, Request& request) {
        if (index == (int)middlewares.size()) {
            finalHandler.handle(request);
            return;
        }
        auto current = middlewares[index];
        current->handle(request, [this, index, &request]() { execute(index + 1, request); });
    }
};

int main() {
    vector<shared_ptr<Middleware>> chainMiddlewares = { make_shared<LoggingMiddleware>(), make_shared<AuthMiddleware>() };
    MiddlewareChain chain(chainMiddlewares, FinalHandler());

    cout << "Request with a valid token:" << endl;
    Request req1("/orders", "valid-token");
    chain.run(req1);

    cout << "Request with no token:" << endl;
    Request req2("/orders", "");
    chain.run(req2);

    return 0;
}
